-- Content keys for the expense / receipt / booking-steps / account-label UI (needs_review drafts, RU/EN/TH/ZH).
-- Insert-only: existing keys and translations (possibly edited in admin) are NOT overwritten. Safe to run twice.
-- Run once in the Supabase SQL editor (project burcnghheyzbzffzgmjz). Last line must start with "select".
BEGIN;
ON CONFLICT (key) DO NOTHING;
ON CONFLICT (content_key_id, locale) DO NOTHING;
COMMIT;
